package builtin

import (
	"context"
	"encoding/base64"
	"encoding/json"
	"fmt"
	"net/http"
	"net/http/httptest"
	"os"
	"path/filepath"
	"strings"
	"testing"
)

// onePixelPNG is a real 1x1 PNG, so generated bytes pass the same validation an
// attached image does.
var onePixelPNG = func() []byte {
	raw, err := base64.StdEncoding.DecodeString("iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR4nGP4z8DwHwAFAAH/iZk9HQAAAABJRU5ErkJggg==")
	if err != nil {
		panic(err)
	}
	return raw
}()

func imageGenFor(workDir string, spec ImageGenSpec) imageGen {
	// Mirror Workspace.Tools: the roots a writer tool receives are already
	// symlink-free absolute paths, because confine() resolves the target the
	// same way before comparing.
	return imageGen{workDir: workDir, roots: realRoots([]string{workDir}), spec: spec}
}

func generatedFiles(t *testing.T, dir string) []os.DirEntry {
	t.Helper()
	entries, err := os.ReadDir(filepath.Join(dir, ".reasonix", "generated"))
	if err != nil {
		t.Fatalf("read generated dir: %v", err)
	}
	return entries
}

func TestGenerateImageStoresInlineImage(t *testing.T) {
	dir := t.TempDir()
	var body map[string]any
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodPost || r.URL.Path != "/v1/images/generations" {
			t.Errorf("request = %s %s", r.Method, r.URL.Path)
		}
		if got := r.Header.Get("Authorization"); got != "Bearer test-key" {
			t.Errorf("authorization = %q", got)
		}
		if err := json.NewDecoder(r.Body).Decode(&body); err != nil {
			t.Errorf("decode request body: %v", err)
		}
		fmt.Fprintf(w, `{"data":[{"b64_json":%q}]}`, base64.StdEncoding.EncodeToString(onePixelPNG))
	}))
	defer srv.Close()

	tl := imageGenFor(dir, ImageGenSpec{BaseURL: srv.URL + "/v1", APIKey: "test-key", Model: "Tongyi-MAI/Z-Image-Turbo", Size: "512x512"})
	text, images, err := tl.ExecuteWithImages(context.Background(), json.RawMessage(`{"prompt":"a red cube"}`))
	if err != nil {
		t.Fatalf("ExecuteWithImages: %v", err)
	}
	if body["model"] != "Tongyi-MAI/Z-Image-Turbo" || body["prompt"] != "a red cube" || body["size"] != "512x512" {
		t.Fatalf("request body = %v", body)
	}
	if len(images) != 1 || !strings.HasPrefix(images[0], "data:image/png;base64,") {
		t.Fatalf("images = %v", images)
	}
	if !strings.Contains(text, "[image: image/png, 1x1]") {
		t.Fatalf("text = %q", text)
	}
	entries := generatedFiles(t, dir)
	if len(entries) != 1 {
		t.Fatalf("generated files = %v", entries)
	}
	onDisk, err := os.ReadFile(filepath.Join(dir, ".reasonix", "generated", entries[0].Name()))
	if err != nil || string(onDisk) != string(onePixelPNG) {
		t.Fatalf("saved bytes differ: %v", err)
	}
}

func TestGenerateImageDownloadsURLResult(t *testing.T) {
	dir := t.TempDir()
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		switch r.URL.Path {
		case "/images/generations":
			fmt.Fprintf(w, `{"images":[{"url":%q}]}`, "http://"+r.Host+"/img.png")
		case "/img.png":
			w.Header().Set("Content-Type", "image/png")
			w.Write(onePixelPNG)
		default:
			t.Errorf("unexpected path %q", r.URL.Path)
		}
	}))
	defer srv.Close()

	tl := imageGenFor(dir, ImageGenSpec{BaseURL: srv.URL, APIKey: "test-key", Model: "black-forest-labs/FLUX.1-schnell"})
	text, images, err := tl.ExecuteWithImages(context.Background(), json.RawMessage(`{"prompt":"a green cube","path":"out/hero.png"}`))
	if err != nil {
		t.Fatalf("ExecuteWithImages: %v", err)
	}
	if len(images) != 1 || !strings.HasPrefix(images[0], "data:image/png;base64,") {
		t.Fatalf("images = %v", images)
	}
	if !strings.Contains(text, "out/hero.png") {
		t.Fatalf("text = %q", text)
	}
	onDisk, err := os.ReadFile(filepath.Join(dir, "out", "hero.png"))
	if err != nil || string(onDisk) != string(onePixelPNG) {
		t.Fatalf("explicit path was not honored: %v", err)
	}
}

func TestGenerateImageRetriesWithImageSize(t *testing.T) {
	dir := t.TempDir()
	var attempts []map[string]any
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		switch r.URL.Path {
		case "/images/generations":
			var body map[string]any
			if err := json.NewDecoder(r.Body).Decode(&body); err != nil {
				t.Errorf("decode request body: %v", err)
			}
			attempts = append(attempts, body)
			if len(attempts) == 1 {
				w.WriteHeader(http.StatusBadRequest)
				fmt.Fprint(w, `{"error":{"message":"unknown parameter size; use image_size"}}`)
				return
			}
			fmt.Fprintf(w, `{"images":[{"url":%q}]}`, "http://"+r.Host+"/img.png")
		case "/img.png":
			w.Write(onePixelPNG)
		default:
			t.Errorf("unexpected path %q", r.URL.Path)
		}
	}))
	defer srv.Close()

	tl := imageGenFor(dir, ImageGenSpec{BaseURL: srv.URL, Model: "Tongyi-MAI/Z-Image-Turbo", Size: "768x1024"})
	if _, _, err := tl.ExecuteWithImages(context.Background(), json.RawMessage(`{"prompt":"a blue cube"}`)); err != nil {
		t.Fatalf("ExecuteWithImages: %v", err)
	}
	if len(attempts) != 2 {
		t.Fatalf("attempts = %d, want 2", len(attempts))
	}
	if attempts[0]["size"] != "768x1024" {
		t.Fatalf("first attempt = %v", attempts[0])
	}
	if attempts[1]["image_size"] != "768x1024" {
		t.Fatalf("retry attempt = %v", attempts[1])
	}
	if _, ok := attempts[1]["size"]; ok {
		t.Fatalf("retry must drop size: %v", attempts[1])
	}
}

func TestGenerateImageRequiresConfiguration(t *testing.T) {
	tl := imageGen{}
	if tl.ProviderVisible(context.Background()) {
		t.Fatal("unconfigured generate_image must stay hidden from the model")
	}
	if _, _, err := tl.ExecuteWithImages(context.Background(), json.RawMessage(`{"prompt":"x"}`)); err == nil || !strings.Contains(err.Error(), "not configured") {
		t.Fatalf("err = %v", err)
	}
	configured := imageGenFor(t.TempDir(), ImageGenSpec{BaseURL: "https://example.test/v1", Model: "m"})
	if !configured.ProviderVisible(context.Background()) {
		t.Fatal("configured generate_image should be visible")
	}
}

func TestGenerateImageDeclaresConfiguredOutputDirectory(t *testing.T) {
	dir := t.TempDir()
	tl := imageGenFor(dir, ImageGenSpec{BaseURL: "https://example.test/v1", Model: "m", OutDir: "art"})
	decl, err := tl.DeclareWriteAccess(json.RawMessage(`{"prompt":"x"}`))
	if err != nil {
		t.Fatalf("DeclareWriteAccess: %v", err)
	}
	want := filepath.Join(dir, "art")
	if len(decl.Directories) != 1 || decl.Directories[0] != want {
		t.Fatalf("directories = %v, want %q", decl.Directories, want)
	}

	explicit, err := tl.DeclareWriteAccess(json.RawMessage(`{"prompt":"x","path":"nested/hero.png"}`))
	if err != nil {
		t.Fatalf("DeclareWriteAccess: %v", err)
	}
	if want := filepath.Join(dir, "nested"); len(explicit.Directories) != 1 || explicit.Directories[0] != want {
		t.Fatalf("directories = %v, want %q", explicit.Directories, want)
	}
}

func TestParseImageGenResponseVariants(t *testing.T) {
	cases := []struct {
		name    string
		raw     string
		wantB64 string
		wantURL string
		wantErr string
	}{
		{name: "openai data url", raw: `{"data":[{"url":"https://example.test/a.png"}]}`, wantURL: "https://example.test/a.png"},
		{name: "openai data b64", raw: `{"data":[{"b64_json":"QUJD"}]}`, wantB64: "QUJD"},
		{name: "siliconflow images", raw: `{"images":[{"url":"https://example.test/b.png"}],"timings":{}}`, wantURL: "https://example.test/b.png"},
		{name: "images b64", raw: `{"images":[{"b64_json":"QUJD"}]}`, wantB64: "QUJD"},
		{name: "error envelope", raw: `{"error":{"message":"model not found"}}`, wantErr: "model not found"},
		{name: "empty", raw: `{"data":[]}`, wantErr: "no image data"},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			ref, err := parseImageGenResponse([]byte(tc.raw))
			if tc.wantErr != "" {
				if err == nil || !strings.Contains(err.Error(), tc.wantErr) {
					t.Fatalf("err = %v, want %q", err, tc.wantErr)
				}
				return
			}
			if err != nil {
				t.Fatalf("parseImageGenResponse: %v", err)
			}
			if ref.b64 != tc.wantB64 || ref.url != tc.wantURL {
				t.Fatalf("ref = %+v, want b64=%q url=%q", ref, tc.wantB64, tc.wantURL)
			}
		})
	}
}

func TestGenerateImageWrappedBase64AndEndpointError(t *testing.T) {
	dir := t.TempDir()
	wrapped := base64.StdEncoding.EncodeToString(onePixelPNG)
	wrapped = wrapped[:12] + "\n" + wrapped[12:]
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if strings.Contains(r.URL.Path, "boom") {
			w.WriteHeader(http.StatusUnauthorized)
			fmt.Fprint(w, `{"error":{"message":"invalid api key"}}`)
			return
		}
		fmt.Fprintf(w, `{"data":[{"b64_json":%q}]}`, wrapped)
	}))
	defer srv.Close()

	tl := imageGenFor(dir, ImageGenSpec{BaseURL: srv.URL, Model: "m"})
	if _, _, err := tl.ExecuteWithImages(context.Background(), json.RawMessage(`{"prompt":"x"}`)); err != nil {
		t.Fatalf("wrapped base64 should decode: %v", err)
	}

	failing := imageGenFor(dir, ImageGenSpec{BaseURL: srv.URL + "/boom", Model: "m"})
	_, _, err := failing.ExecuteWithImages(context.Background(), json.RawMessage(`{"prompt":"x"}`))
	if err == nil || !strings.Contains(err.Error(), "invalid api key") {
		t.Fatalf("err = %v", err)
	}
}
